import java.util.*; import java.io.*; public class Main { public static void main(String[] args) throws IOException { BufferedReader br = new BufferedReader(new InputStreamReader(System.in)); PrintWriter out = new PrintWriter(System.out); boolean[] isPrime = new boolean[201]; Arrays.fill(isPrime, true); isPrime[0] = isPrime[1] = false; for (int p = 2; p * p <= 200; p++) { if (isPrime[p]) { for (int i = p * p; i <= 200; i += p) isPrime[i] = false; } } List<Integer> primes = new ArrayList<>(); for (int i = 2; i <= 200; i++) if (isPrime[i]) primes.add(i); boolean[] isSemiPrime = new boolean[201]; for (int i = 0; i < primes.size(); i++) { for (int j = i + 1; j < primes.size(); j++) { int prod = primes.get(i) * primes.get(j); if (prod <= 200) isSemiPrime[prod] = true; } } int t = Integer.parseInt(br.readLine()); while (t-- > 0) { int n = Integer.parseInt(br.readLine()); boolean found = false; for (int i = 1; i <= n; i++) { if (isSemiPrime[i] && isSemiPrime[n - i]) { found = true; break; } } if (found) out.println("YES"); else out.println("NO"); } out.flush(); out.close(); } }